function isLoyalCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function loyaltyDiscountOf(policyBasePremium: number, customer: Customer): number {
  return isLoyalCustomer(customer) ? policyBasePremium * LOYALTY_DISCOUNT_RATE : 0;
}

function roundPremiumInMHPCOsFavor(premium: number): number {
  return Math.ceil(premium);
}

function quotePremium(items: Item[], customer: Customer): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  const loyaltyDiscount = loyaltyDiscountOf(policyBasePremium, customer);
  const riskSurcharges = itemRiskSurchargesOf(items);
  return roundPremiumInMHPCOsFavor(
    policyBasePremium + riskSurcharges + firstInsuranceSurcharge - loyaltyDiscount + PROCESSING_FEE,
  );
}

export function processScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items, scenario.customer) })) };
}

