}

// The total payout per policy is capped at twice the (unmodified) insurance sum.
function payoutCapOf(policyItems: Item[]): number {
  return insuranceSumOf(policyItems) * CAP_MULTIPLIER;
}

function claimPayout(damages: Damage[]): number {
  return damages.reduce((sum, damage) => sum + damage.amount - DEDUCTIBLE_PER_DAMAGE, 0);
}

function settleClaim(policyItems: Item[], damages: Damage[]): { payout: number; remainingCap: number } {
  const payout = claimPayout(damages);
