import {
  type ClaimSettlement,
  type Damage,
  payoutCapOf,
  settleClaim,
} from "./claim-settlement.js";
import type { Item } from "./item-catalog.js";
import { type Customer, quotePremium } from "./premium.js";

export type { ClaimSettlement, Customer, Damage, Item };

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | ClaimSettlement;

// Every quote after the scenario's first one counts as a follow-up contract.
function hasEarlierContract(steps: Step[], index: number): boolean {
  return steps.slice(0, index).some((earlier) => earlier.op === "quote");
}

// A claim refers to its policy by the index of the quote step that issued it.
function claimedPolicyOf(steps: Step[], claim: ClaimStep): QuoteStep {
  return steps[claim.policy] as QuoteStep;
}

// Remaining caps are tracked per policy: before its first claim, a policy has its full payout cap.
function settleClaimAgainstPolicy(
  steps: Step[],
  claim: ClaimStep,
  remainingCaps: Map<number, number>,
): ClaimSettlement {
  const policyItems = claimedPolicyOf(steps, claim).items;
  const remainingCap =
    remainingCaps.get(claim.policy) ?? payoutCapOf(policyItems);
  const settlement = settleClaim(
    policyItems,
    claim.incident.damages,
    remainingCap,
  );
  remainingCaps.set(claim.policy, settlement.remainingCap);
  return settlement;
}

export function processScenario(scenario: Scenario): { results: StepResult[] } {
  const remainingCaps = new Map<number, number>();
  return {
    results: scenario.steps.map((step, index) =>
      step.op === "claim"
        ? settleClaimAgainstPolicy(scenario.steps, step, remainingCaps)
        : {
            premium: quotePremium(
              step.items,
              scenario.customer,
              hasEarlierContract(scenario.steps, index),
            ),
          },
    ),
  };
}
import { type Item, enchantmentLevelOf, insuranceValueOf } from "./item-catalog.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;
const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
const FULL_REIMBURSEMENT_RATE = 1;

// The insurance sum adds up the listed insurance values; premium modifiers and the
// component block discount affect the premium only, never the insurance sum.
function insuranceSumOf(items: Item[]): number {
  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
}

// The total payout per policy is capped at twice the insurance sum.
export function payoutCapOf(policyItems: Item[]): number {
  return insuranceSumOf(policyItems) * CAP_MULTIPLIER;
}

function isReimbursedAtReducedRate(damagedItem: Item): boolean {
  return enchantmentLevelOf(damagedItem) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
}

// Damage is fully reimbursed (e.g. dragon material) unless the item is highly enchanted.
function reimbursementRateOf(damagedItem: Item): number {
  return isReimbursedAtReducedRate(damagedItem)
    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    : FULL_REIMBURSEMENT_RATE;
}

function reimbursementOf(damagedItem: Item, amount: number): number {
  return amount * reimbursementRateOf(damagedItem);
}

// A damage refers to the first insured item of the damaged type.
function damagedPolicyItemOf(policyItems: Item[], damage: Damage): Item {
  return policyItems.find((item) => item.type === damage.itemType) as Item;
}

function damagePayoutOf(damagedItem: Item, amount: number): number {
  return reimbursementOf(damagedItem, amount) - DEDUCTIBLE_PER_DAMAGE;
}

function claimPayout(policyItems: Item[], damages: Damage[]): number {
  return damages.reduce(
    (sum, damage) =>
      sum +
      damagePayoutOf(damagedPolicyItemOf(policyItems, damage), damage.amount),
    0,
  );
}

function roundPayoutInMHPCOsFavor(payout: number): number {
  return Math.floor(payout);
}

export function settleClaim(
  policyItems: Item[],
  damages: Damage[],
  remainingCap: number,
): ClaimSettlement {
  const payout = Math.min(
    roundPayoutInMHPCOsFavor(claimPayout(policyItems, damages)),
    remainingCap,
  );
  return { payout, remainingCap: remainingCap - payout };
}
import { describe, it } from "vitest";

describe("claim-office CLI", () => {
  it.todo("reads the scenario JSON from stdin and writes {results} JSON to stdout with exit code 0");
  it.todo("quote with unknown item type (broomstick) -> non-zero exit, error on stderr, no results on stdout");
  it.todo("claim damaging an amulet when only a sword is insured -> non-zero exit, error on stderr");
  it.todo("claim damaging an item of unknown type -> non-zero exit, error on stderr");
  it.todo("claim with damage amount -200 -> non-zero exit, error on stderr");
  it.todo("claim with two sword damages but only one sword insured -> non-zero exit, whole claim rejected");
});

